# -*- coding: utf-8 -*-
"""Butir pencegahan perkawinan bagian B: alasan pencegahan huruf A sampai H dan kemudaratan perkawinan. Agen W2b-B."""
from isi_pencegahan import S


def AL(huruf, **lain):
    return dict({'alasan': huruf}, **lain)


# ------------------------------------------------------------------ alasan A: masih terikat perkawinan lain (urutan 61-63)
S(id='a-status', pokok='pp-pc-alasan-a', urut_abs=61, tingkat='inti', keadaan=AL('A'),
  teks='Apa yang menunjukkan bahwa salah seorang calon mempelai masih terikat perkawinan yang sah dengan orang lain dan dari mana saksi mengetahuinya ?',
  varian=['Bagaimana status perkawinan salah seorang calon mempelai dengan orang lain dan dari mana saksi mengetahui ikatan itu ?'],
  hal='status perkawinan salah seorang calon mempelai dengan orang lain', m='status perkawinan salah seorang calon mempelai dengan orang lain', fam='tahu',
  K=(['salah seorang calon mempelai masih berstatus suami atau istri sah orang lain dan perkawinan itu masih berlangsung',
      'salah seorang calon mempelai masih terikat perkawinan yang sah dengan orang lain dan ikatan itu masih berjalan sampai sekarang'],
     ['perkawinan salah seorang calon mempelai dengan orang lain masih sah dan masih berlaku sampai sekarang',
      'salah seorang calon mempelai masih mempunyai pasangan yang sah dan mereka masih terikat sebagai suami istri']),
  P=(['salah seorang calon mempelai masih berstatus suami atau istri sah orang lain', 'salah seorang calon mempelai masih terikat perkawinan dengan orang lain'],
     ['perkawinan salah seorang calon mempelai dengan orang lain masih sah', 'salah seorang calon mempelai masih mempunyai pasangan yang sah']),
  A=['salah seorang calon mempelai masih terikat perkawinan yang sah dengan orang lain', 'calon mempelai itu masih tercatat sebagai suami atau istri orang lain'],
  B=['perkawinan terdahulu calon mempelai itu sudah diputus oleh pengadilan', 'calon mempelai itu sudah resmi bercerai dari pasangannya yang terdahulu'],
  beda_pada='peristiwa', beda_maksud='versi A: calon mempelai masih terikat perkawinan sah; versi B: perkawinan terdahulu sudah diputus pengadilan - berselisih pada PERISTIWA/status perkawinan',
  ragam=[dict(keadaan={'terikatPada': 'calon-suami'}, m='status calon suami yang masih beristri', fam='tahu',
              K=(['calon suami masih beristri sah dan ikatan perkawinannya dengan istrinya itu masih berlangsung',
                  'calon suami masih berstatus suami yang sah dari istrinya dan ikatan itu masih berjalan sampai sekarang'],
                 ['istri sah calon suami masih menjadi istrinya sampai sekarang',
                  'calon suami masih mempunyai istri yang sah dan mereka masih terikat sebagai suami istri'])),
         dict(keadaan={'terikatPada': 'calon-istri'}, m='status calon istri yang masih bersuami', fam='tahu',
              K=(['calon istri masih bersuami sah dan ikatan perkawinannya dengan suaminya itu masih berlangsung',
                  'calon istri masih berstatus istri yang sah dari suaminya dan ikatan itu masih berjalan sampai sekarang'],
                 ['suami sah calon istri masih menjadi suaminya sampai sekarang',
                  'calon istri masih mempunyai suami yang sah dan mereka masih terikat sebagai suami istri']))])

S(id='a-poligami-izin', pokok='pp-pc-alasan-a', urut_abs=62, tingkat='inti', keadaan=AL('A', terikatPada='calon-suami'),
  teks='Apakah calon suami yang masih beristri itu sudah memperoleh izin dari Pengadilan Agama untuk beristri lebih dari seorang ?',
  varian=['Apakah ada izin poligami dari Pengadilan Agama bagi calon suami yang masih beristri itu ?'],
  hal='izin poligami calon suami dari Pengadilan Agama', m='izin poligami calon suami dari Pengadilan Agama', fam='tahu',
  K=(['calon suami hendak menikah lagi di luar izin Pengadilan Agama untuk beristri lebih dari seorang',
      'rencana perkawinan calon suami dengan istri kedua dijalankan di luar izin dari Pengadilan Agama'],
     ['calon suami melangsungkan rencana beristri lagi itu di luar sepengetahuan Pengadilan Agama',
      'perkawinan kedua yang direncanakan calon suami diatur sendiri olehnya di luar putusan Pengadilan Agama']),
  P=(['calon suami hendak menikah lagi di luar izin Pengadilan Agama', 'rencana perkawinan calon suami dengan istri kedua dijalankan di luar izin Pengadilan Agama'],
     ['calon suami melangsungkan rencana beristri lagi itu di luar sepengetahuan Pengadilan Agama', 'perkawinan kedua calon suami diatur sendiri olehnya di luar putusan Pengadilan Agama']),
  A=['calon suami tidak pernah mengajukan permohonan izin poligami ke Pengadilan Agama', 'permohonan izin poligami tidak pernah diajukan oleh calon suami'],
  B=['calon suami sudah mengajukan permohonan izin poligami ke Pengadilan Agama dan menunggu putusan', 'permohonan izin poligami calon suami sedang diperiksa di Pengadilan Agama'],
  beda_pada='peristiwa', beda_maksud='versi A: calon suami tidak pernah mengajukan izin poligami; versi B: calon suami sudah mengajukan dan menunggu putusan - berselisih pada PERISTIWA')

S(id='a-istri-sah', pokok='pp-pc-alasan-a', urut_abs=63, tingkat='pilihan', keadaan=AL('A', terikatPada='calon-suami'), fam='hadir',
  teks='Apakah istri sah calon suami itu mengetahui dan menyetujui rencana suaminya menikah lagi ?',
  varian=['Bagaimana sikap istri sah calon suami terhadap rencana suaminya menikah lagi ?'],
  hal='sikap istri sah calon suami atas rencana suaminya menikah lagi', m='sikap istri sah calon suami atas rencana suaminya menikah lagi',
  K=(['istri sah calon suami menolak rencana suaminya menikah lagi dan menyatakan keberatannya kepada keluarga',
      'istri sah calon suami berkeberatan atas rencana suaminya beristri lagi dan mengatakan hal itu di depan keluarga'],
     ['keberatan istri sah calon suami atas rencana suaminya menikah lagi sudah ia nyatakan kepada keluarga',
      'di depan keluarga istri sah calon suami berkata bahwa ia menolak dimadu oleh suaminya']),
  M='K',
  P=(['istri sah calon suami menolak rencana suaminya menikah lagi', 'istri sah calon suami berkeberatan atas rencana suaminya beristri lagi'],
     ['istri sah calon suami sudah menyatakan keberatannya', 'istri sah calon suami menolak dimadu oleh suaminya']),
  A=['istri sah calon suami menolak rencana suaminya menikah lagi', 'istri sah calon suami berkeberatan dimadu oleh suaminya'],
  B=['istri sah calon suami mengetahui dan merelakan rencana suaminya menikah lagi', 'istri sah calon suami menyetujui suaminya beristri lagi'],
  beda_pada='peristiwa', beda_maksud='versi A: istri sah menolak rencana suaminya; versi B: istri sah merelakan - berselisih pada PERISTIWA/sikap istri sah')

# ------------------------------------------------------------------ alasan B: belum cukup umur (urutan 71-73)
S(id='b-umur', pokok='pp-pc-alasan-b', urut_abs=71, tingkat='inti', keadaan=AL('B'),
  teks='Berapa umur calon mempelai yang disebut masih di bawah umur itu dan dari mana saksi mengetahui umurnya ?',
  varian=['Dari mana saksi mengetahui umur calon mempelai yang masih di bawah umur itu dan berapa umurnya sekarang ?'],
  hal='umur calon mempelai yang masih di bawah umur', m='umur calon mempelai yang masih di bawah umur', fam='tahu',
  K=(['salah seorang calon mempelai masih berusia di bawah sembilan belas tahun dan dikenal keluarganya sejak kecil',
      'umur salah seorang calon mempelai masih di bawah batas sembilan belas tahun sebagaimana tampak dari masa pertumbuhannya'],
     ['salah seorang calon mempelai masih berusia di bawah sembilan belas tahun dan tumbuh di lingkungan yang sama dengan saksi',
      'usia salah seorang calon mempelai masih di bawah sembilan belas tahun sesuai tahun kelahirannya']),
  P=(['salah seorang calon mempelai masih berusia di bawah sembilan belas tahun', 'umur salah seorang calon mempelai masih di bawah batas sembilan belas tahun'],
     ['salah seorang calon mempelai masih berusia di bawah sembilan belas tahun sesuai tahun lahirnya', 'usia salah seorang calon mempelai masih di bawah sembilan belas tahun']),
  A=['salah seorang calon mempelai masih di bawah sembilan belas tahun', 'umur salah seorang calon mempelai masih di bawah batas sembilan belas tahun'],
  B=['kedua calon mempelai sudah berumur lebih dari sembilan belas tahun', 'umur kedua calon mempelai sudah melewati batas sembilan belas tahun'],
  beda_pada='jumlah', beda_maksud='versi A: salah seorang calon mempelai di bawah sembilan belas tahun; versi B: keduanya sudah lebih dari sembilan belas tahun - berselisih pada JUMLAH (umur)')

S(id='b-dispensasi', pokok='pp-pc-alasan-b', urut_abs=72, tingkat='pilihan', keadaan=AL('B'),
  teks='Apakah calon mempelai yang masih di bawah umur itu sudah mendapat penetapan dispensasi kawin dari pengadilan ?',
  varian=['Apakah keluarga calon mempelai yang masih di bawah umur itu sudah mengurus dispensasi kawin ke pengadilan ?'],
  hal='dispensasi kawin bagi calon mempelai yang masih di bawah umur', m='dispensasi kawin bagi calon mempelai yang masih di bawah umur', fam='tahu',
  K=(['calon mempelai yang masih di bawah umur itu hendak menikah tanpa penetapan dispensasi kawin dari pengadilan',
      'rencana perkawinan itu berjalan tanpa dispensasi kawin dari pengadilan bagi calon mempelai yang masih di bawah umur'],
     ['sampai sekarang calon mempelai yang masih di bawah umur itu belum memiliki penetapan dispensasi kawin',
      'dispensasi kawin dari pengadilan belum ada untuk calon mempelai yang masih di bawah umur itu']),
  P=(['calon mempelai yang masih di bawah umur itu hendak menikah tanpa dispensasi kawin', 'rencana perkawinan itu berjalan tanpa penetapan dispensasi kawin'],
     ['calon mempelai yang masih di bawah umur itu belum memiliki dispensasi kawin', 'dispensasi kawin untuk calon mempelai itu belum ada']),
  A=['keluarga calon mempelai tidak pernah mengurus dispensasi kawin ke pengadilan', 'tidak ada permohonan dispensasi kawin yang didaftarkan keluarga ke pengadilan'],
  B=['permohonan dispensasi kawin sudah didaftarkan keluarga ke pengadilan', 'keluarga calon mempelai sudah mengajukan dispensasi kawin dan sedang menunggu sidang'],
  beda_pada='peristiwa', beda_maksud='versi A: keluarga tidak pernah mengurus dispensasi kawin; versi B: permohonan dispensasi sudah didaftarkan - berselisih pada PERISTIWA')

S(id='m-kesiapan', pokok='pp-pc-kemudaratan', urut_abs=73, tingkat='tambahan', keadaan=AL('B'),
  teks='Bagaimana kesiapan calon mempelai yang masih di bawah umur untuk berumah tangga misalnya pendidikan, pekerjaan dan kemandiriannya ?',
  varian=['Apakah calon mempelai yang masih di bawah umur itu masih sekolah atau sudah bekerja dan siapa yang menanggung hidupnya ?'],
  hal='kesiapan calon mempelai yang masih di bawah umur untuk berumah tangga', m='kesiapan calon mempelai yang masih di bawah umur untuk berumah tangga', fam='tahu',
  K=(['calon mempelai yang masih di bawah umur itu masih bersekolah dan bergantung pada orang tuanya',
      'calon mempelai yang masih di bawah umur itu masih menempuh pendidikan dan hidupnya masih ditanggung orang tua'],
     ['kehidupan calon mempelai yang masih di bawah umur itu masih bergantung pada orang tuanya dan pendidikannya masih berjalan',
      'calon mempelai yang masih di bawah umur itu masih duduk di bangku sekolah dan nafkahnya masih dipenuhi orang tuanya']),
  P=(['calon mempelai yang masih di bawah umur itu masih bersekolah', 'calon mempelai yang masih di bawah umur itu masih menempuh pendidikan'],
     ['kehidupan calon mempelai itu masih bergantung pada orang tuanya', 'calon mempelai itu masih duduk di bangku sekolah']))

# ------------------------------------------------------------------ alasan C: nasab, semenda, sesusuan (urutan 81-83)
S(id='c-nasab', pokok='pp-pc-alasan-c', urut_abs=81, tingkat='inti', keadaan=AL('C', jenisLarangan='nasab'),
  teks='Apa hubungan darah antara calon suami dan calon istri sehingga mereka dilarang menikah dan dari mana saksi mengetahui hubungan itu ?',
  varian=['Bagaimana pertalian darah antara calon suami dan calon istri yang menjadi larangan perkawinan dan dari mana saksi mengetahuinya ?'],
  hal='hubungan darah calon suami dengan calon istri', m='hubungan darah calon suami dengan calon istri', fam='tahu',
  K=(['calon suami dan calon istri mempunyai hubungan darah dekat yang dilarang menikah menurut hukum Islam',
      'antara calon suami dan calon istri ada hubungan nasab karena berasal dari satu keturunan yang sama'],
     ['calon suami dan calon istri masih bersaudara menurut garis keturunan dan keduanya haram menikah satu sama lain',
      'hubungan darah antara calon suami dan calon istri sangat dekat sebagaimana tampak dari silsilah keluarga']),
  P=(['calon suami dan calon istri mempunyai hubungan darah dekat', 'antara calon suami dan calon istri ada hubungan nasab'],
     ['calon suami dan calon istri masih bersaudara menurut garis keturunan', 'hubungan darah antara calon suami dan calon istri sangat dekat']),
  A=['calon suami adalah paman dari calon istri', 'calon istri adalah keponakan kandung dari calon suami'],
  B=['calon suami dan calon istri hanya sepupu jauh', 'hubungan calon suami dengan calon istri sebatas sepupu yang jauh'],
  beda_pada='peristiwa', beda_maksud='versi A: calon suami adalah paman calon istri; versi B: keduanya hanya sepupu jauh - berselisih pada PERISTIWA/derajat hubungan darah')

S(id='c-semenda', pokok='pp-pc-alasan-c', urut_abs=82, tingkat='inti', keadaan=AL('C', jenisLarangan='semenda'),
  teks='Apa hubungan semenda antara calon suami dan calon istri atau keluarga mereka sehingga perkawinan itu dilarang dan dari mana saksi mengetahuinya ?',
  varian=['Hubungan apa yang terjadi karena perkawinan terdahulu antara calon suami dan calon istri sehingga mereka dilarang menikah ?'],
  hal='hubungan semenda calon suami dengan calon istri', m='hubungan semenda calon suami dengan calon istri', fam='tahu',
  K=(['calon suami dan calon istri terikat hubungan semenda karena perkawinan keluarga mereka sebelumnya',
      'antara calon suami dan calon istri ada hubungan sebagai mertua dan menantu atau sebagai orang tua tiri dan anak tiri'],
     ['perkawinan terdahulu di antara keluarga mereka melahirkan hubungan semenda yang menjadi larangan bagi calon suami dan calon istri',
      'calon suami dan calon istri berhubungan sebagai mertua dan menantu atau orang tua tiri dan anak tiri karena perkawinan sebelumnya']),
  P=(['calon suami dan calon istri terikat hubungan semenda', 'antara calon suami dan calon istri ada hubungan sebagai mertua dan menantu'],
     ['perkawinan terdahulu di antara keluarga mereka melahirkan hubungan semenda', 'calon suami dan calon istri berhubungan sebagai orang tua tiri dan anak tiri']),
  A=['calon istri adalah anak tiri dari calon suami', 'calon suami pernah menjadi ayah tiri bagi calon istri'],
  B=['calon istri adalah anak tetangga dan tidak ada hubungan keluarga dengan calon suami', 'antara calon suami dan calon istri tidak ada hubungan keluarga apa pun'],
  beda_pada='peristiwa', beda_maksud='versi A: calon istri anak tiri calon suami; versi B: tidak ada hubungan keluarga - berselisih pada PERISTIWA/hubungan semenda')

S(id='c-sesusuan', pokok='pp-pc-alasan-c', urut_abs=83, tingkat='inti', keadaan=AL('C', jenisLarangan='sesusuan'),
  teks='Apakah calon suami dan calon istri pernah disusui oleh perempuan yang sama dan dari mana saksi mengetahui hal itu ?',
  varian=['Apakah calon suami dan calon istri bersaudara sesusuan karena menyusu pada ibu susu yang sama dan siapa yang menerangkannya ?'],
  hal='hubungan sesusuan calon suami dengan calon istri', m='hubungan sesusuan calon suami dengan calon istri', fam='tahu',
  K=(['calon suami dan calon istri pernah disusui oleh perempuan yang sama pada masa bayi mereka',
      'pada waktu bayi calon suami dan calon istri menyusu kepada ibu susu yang sama'],
     ['ibu susu calon suami dan calon istri adalah orang yang sama sehingga mereka bersaudara sesusuan',
      'calon suami dan calon istri menjadi saudara sesusuan karena disusui oleh satu perempuan yang sama']),
  P=(['calon suami dan calon istri pernah disusui oleh perempuan yang sama', 'pada waktu bayi calon suami dan calon istri menyusu kepada ibu susu yang sama'],
     ['ibu susu calon suami dan calon istri adalah orang yang sama', 'calon suami dan calon istri bersaudara sesusuan']),
  A=['calon suami dan calon istri disusui oleh perempuan yang sama berkali-kali', 'perempuan yang sama menyusui calon suami dan calon istri berulang kali'],
  B=['calon suami dan calon istri hanya sekali menyusu pada perempuan yang sama', 'penyusuan oleh perempuan yang sama terjadi sekali saja pada keduanya'],
  beda_pada='jumlah', beda_maksud='versi A: disusui berkali-kali oleh perempuan yang sama; versi B: hanya sekali - berselisih pada JUMLAH penyusuan')

# ------------------------------------------------------------------ alasan D: masa iddah (urutan 91-92)
S(id='d-putus', pokok='pp-pc-alasan-d', urut_abs=91, tingkat='inti', keadaan=AL('D'),
  teks='Karena apa dan sejak kapan perkawinan calon istri yang terdahulu berakhir dan dari mana saksi mengetahuinya ?',
  varian=['Sebab apa yang mengakhiri perkawinan calon istri dengan suaminya yang terdahulu dan kapan itu terjadi ?'],
  hal='berakhirnya perkawinan calon istri yang terdahulu', m='berakhirnya perkawinan calon istri yang terdahulu', fam='tahu',
  K=(['perkawinan calon istri yang terdahulu baru berakhir beberapa waktu lalu dan masa iddahnya masih berjalan',
      'calon istri baru putus dari perkawinan sebelumnya dan masa iddahnya masih dalam hitungan'],
     ['sejak perkawinan calon istri dengan suami terdahulu berakhir masa iddahnya sedang berjalan',
      'pernikahan calon istri yang lama baru saja berakhir dan masa tunggunya masih berlangsung']),
  P=(['perkawinan calon istri yang terdahulu baru berakhir beberapa waktu lalu', 'calon istri baru putus dari perkawinan sebelumnya'],
     ['perkawinan calon istri dengan suami terdahulu berakhir beberapa waktu lalu',
      'pernikahan calon istri yang lama baru saja berakhir']),
  A=['perkawinan terdahulu calon istri berakhir baru-baru ini', 'calon istri baru saja putus dari suami yang terdahulu'],
  B=['perkawinan terdahulu calon istri sudah berakhir lebih dari setahun yang lalu', 'calon istri sudah lama putus dari suami yang terdahulu'],
  beda_pada='waktu', beda_maksud='versi A: perkawinan terdahulu berakhir baru-baru ini; versi B: sudah berakhir lebih dari setahun - berselisih pada WAKTU berakhirnya perkawinan',
  ragam=[dict(keadaan={'sebabPutus': 'cerai'}, m='berakhirnya perkawinan calon istri karena perceraian', fam='tahu',
              K=(['calon istri baru bercerai dari suaminya dan masa iddah akibat perceraian itu masih berjalan',
                  'perceraian calon istri dengan suami terdahulu baru terjadi dan masa iddahnya masih dalam hitungan'],
                 ['sejak calon istri bercerai dari suaminya masa iddahnya sedang berlangsung',
                  'calon istri baru saja diceraikan atau bercerai dari suaminya dan masa tunggunya masih berjalan'])),
         dict(keadaan={'sebabPutus': 'meninggal'}, m='berakhirnya perkawinan calon istri karena suami meninggal dunia', fam='tahu',
              K=(['suami calon istri baru meninggal dunia dan masa iddah karena kematian itu masih berjalan',
                  'calon istri baru ditinggal mati suaminya dan masa iddahnya masih dalam hitungan'],
                 ['sejak suami calon istri wafat masa iddah calon istri sedang berlangsung',
                  'kematian suami calon istri baru terjadi dan masa tunggunya masih berjalan']))])

S(id='d-jarak', pokok='pp-pc-alasan-d', urut_abs=92, tingkat='pilihan', keadaan=AL('D'),
  teks='Berapa lama jarak waktu antara berakhirnya perkawinan terdahulu calon istri dan rencana akad nikah yang baru ?',
  varian=['Seberapa jauh jarak waktu antara putusnya perkawinan calon istri yang lama dan hari akad nikah yang direncanakan ?'],
  hal='jarak waktu antara berakhirnya perkawinan terdahulu calon istri dan rencana akad nikah', m='jarak waktu antara berakhirnya perkawinan terdahulu calon istri dan rencana akad nikah', fam='tahu',
  K=(['jarak antara berakhirnya perkawinan terdahulu calon istri dan rencana akad nikah yang baru masih sangat singkat',
      'rencana akad nikah yang baru ditetapkan sebelum masa iddah calon istri selesai'],
     ['akad nikah yang baru itu direncanakan dalam masa iddah calon istri yang masih berjalan',
      'waktu antara putusnya perkawinan terdahulu calon istri dan akad nikah yang baru terlalu dekat']),
  P=(['jarak antara berakhirnya perkawinan terdahulu calon istri dan rencana akad nikah yang baru masih sangat singkat', 'rencana akad nikah yang baru ditetapkan sebelum masa iddah selesai'],
     ['akad nikah yang baru itu direncanakan dalam masa iddah calon istri', 'waktu antara putusnya perkawinan terdahulu dan akad nikah yang baru terlalu dekat']),
  A=['jarak antara putusnya perkawinan terdahulu dan akad nikah yang baru hanya beberapa minggu', 'akad nikah yang baru direncanakan hanya beberapa minggu setelah perkawinan terdahulu berakhir'],
  B=['jarak antara putusnya perkawinan terdahulu dan akad nikah yang baru sudah lebih dari tiga bulan', 'akad nikah yang baru direncanakan setelah lewat lebih dari tiga bulan sejak perkawinan terdahulu berakhir'],
  beda_pada='lama', beda_maksud='versi A: jaraknya hanya beberapa minggu; versi B: sudah lebih dari tiga bulan - berselisih pada LAMA jarak waktu')

# ------------------------------------------------------------------ alasan E: perbedaan agama (urutan 101)
S(id='e-agama', pokok='pp-pc-alasan-e', urut_abs=101, tingkat='inti', keadaan=AL('E'),
  teks='Apa agama yang dianut masing-masing calon mempelai dan dari mana saksi mengetahuinya ?',
  varian=['Agama apa yang dianut oleh calon suami dan calon istri dan dari mana saksi mengetahui hal itu ?'],
  hal='agama yang dianut masing-masing calon mempelai', m='agama yang dianut masing-masing calon mempelai', fam='tahu',
  K=(['salah seorang calon mempelai beragama selain Islam sedangkan calon yang lainnya beragama Islam',
      'calon suami dan calon istri berlainan agama karena salah satunya menganut agama selain Islam'],
     ['kedua calon mempelai menganut agama yang berlainan dan itu tampak dari ibadah masing-masing',
      'salah seorang calon mempelai beribadah menurut agama selain Islam sementara calon yang lain beribadah secara Islam']),
  P=(['salah seorang calon mempelai beragama selain Islam', 'calon suami dan calon istri berlainan agama'],
     ['kedua calon mempelai menganut agama yang berlainan', 'salah seorang calon mempelai beribadah menurut agama selain Islam']),
  A=['kedua calon mempelai berlainan agama', 'calon suami dan calon istri menganut agama yang berbeda'],
  B=['salah seorang calon mempelai baru saja menyatakan masuk Islam', 'calon mempelai itu baru beralih memeluk agama Islam beberapa waktu lalu'],
  beda_pada='peristiwa', beda_maksud='versi A: kedua calon mempelai berlainan agama; versi B: salah seorang baru menyatakan masuk Islam - berselisih pada PERISTIWA')

# ------------------------------------------------------------------ alasan F: bekas istri ditalak tiga (urutan 111)
S(id='f-talak-tiga', pokok='pp-pc-alasan-f', urut_abs=111, tingkat='inti', keadaan=AL('F'),
  teks='Apakah saksi mengetahui calon istri pernah ditalak tiga oleh #1029# dan apakah sesudah itu ia pernah menikah dengan laki-laki lain ?',
  varian=['Apakah calon istri pernah dijatuhi talak tiga oleh #1029# dan pernahkah ia menikah dengan laki-laki lain sesudahnya ?'],
  hal='talak tiga calon suami kepada calon istri', m='talak tiga calon suami kepada calon istri dan perkawinan calon istri sesudahnya', fam='tahu',
  K=(['calon istri pernah ditalak tiga kali oleh #1029# dan sesudah itu ia belum pernah menikah dengan laki-laki lain',
      '#1029# pernah menjatuhkan talak tiga kepada calon istri dan sejak itu calon istri belum menikah dengan pria lain'],
     ['setelah ditalak tiga oleh #1029# calon istri belum pernah menikah dengan laki-laki lain',
      'talak tiga yang dijatuhkan #1029# kepada calon istri belum diselingi perkawinan calon istri dengan pria lain']),
  P=(['calon istri pernah ditalak tiga kali oleh #1029#', '#1029# pernah menjatuhkan talak tiga kepada calon istri'],
     ['calon istri ditalak tiga oleh #1029# pada perkawinan mereka yang lalu', 'talak tiga pernah dijatuhkan #1029# kepada calon istri']),
  A=['calon istri ditalak tiga oleh #1029# pada perkawinan mereka yang lalu', '#1029# pernah menjatuhkan talak tiga kepada calon istri'],
  B=['talak yang dijatuhkan #1029# kepada calon istri baru talak satu', '#1029# hanya menjatuhkan talak satu kepada calon istri'],
  beda_pada='jumlah', beda_maksud='versi A: talak yang dijatuhkan adalah talak tiga; versi B: baru talak satu - berselisih pada JUMLAH talak')

# ------------------------------------------------------------------ alasan G: persetujuan calon, izin orang tua, wali (urutan 121-123)
S(id='g-paksa', pokok='pp-pc-alasan-g', urut_abs=121, tingkat='inti', keadaan=AL('G'), fam='hadir',
  teks='Apakah salah seorang calon mempelai dipaksa atau menolak menikah dan bagaimana saksi mengetahui hal itu ?',
  varian=['Apakah ada calon mempelai yang menikah karena dipaksa keluarganya dan dari mana saksi mengetahuinya ?'],
  hal='kerelaan calon mempelai untuk menikah', m='kerelaan calon mempelai untuk menikah',
  K=(['salah seorang calon mempelai dipaksa menikah oleh keluarganya dan ia menyatakan keberatannya',
      'calon mempelai itu menikah karena didesak keluarganya dan ia mengatakan menolak perkawinan tersebut'],
     ['salah seorang calon mempelai berkata di hadapan keluarga bahwa ia dipaksa untuk menikah',
      'tekanan dari keluarga membuat salah seorang calon mempelai menyatakan penolakannya atas perkawinan itu']),
  M='K',
  P=(['salah seorang calon mempelai dipaksa menikah oleh keluarganya', 'calon mempelai itu menikah karena didesak keluarganya'],
     ['salah seorang calon mempelai dipaksa untuk menikah', 'keluarga menekan salah seorang calon mempelai untuk menikah']),
  A=['calon mempelai itu menolak karena dipaksa keluarganya', 'calon mempelai itu dipaksa menikah oleh keluarganya'],
  B=['calon mempelai itu setuju dan menikah atas kemauannya sendiri', 'calon mempelai itu menyatakan rela menikah dengan kehendaknya sendiri'],
  beda_pada='peristiwa', beda_maksud='versi A: calon mempelai dipaksa keluarga; versi B: setuju atas kemauan sendiri - berselisih pada PERISTIWA/kerelaan')

S(id='g-izin-ortu', pokok='pp-pc-alasan-g', urut_abs=122, tingkat='pilihan', keadaan=AL('G'),
  teks='Apakah kedua orang tua atau wali dari calon mempelai yang belum dewasa itu sudah memberi izin untuk perkawinan tersebut ?',
  varian=['Bagaimana sikap kedua orang tua calon mempelai yang belum dewasa itu terhadap izin perkawinan tersebut ?'],
  hal='izin orang tua atas perkawinan calon mempelai yang belum dewasa', m='izin orang tua atas perkawinan calon mempelai yang belum dewasa', fam='tahu',
  K=(['orang tua calon mempelai yang belum dewasa itu tidak memberi izin untuk perkawinan tersebut',
      'kedua orang tua calon mempelai yang belum dewasa itu tidak pernah menandatangani izin perkawinan'],
     ['izin tertulis dari orang tua calon mempelai yang belum dewasa itu tidak ada',
      'untuk perkawinan itu tidak ada izin dari kedua orang tua calon mempelai yang belum dewasa']),
  P=(['orang tua calon mempelai yang belum dewasa itu tidak memberi izin', 'kedua orang tua calon mempelai yang belum dewasa itu tidak pernah menandatangani izin'],
     ['izin tertulis dari orang tua calon mempelai yang belum dewasa itu tidak ada', 'untuk perkawinan calon mempelai yang belum dewasa itu tidak ada izin dari kedua orang tua']),
  A=['orang tua calon mempelai tidak memberi izin untuk perkawinan itu', 'kedua orang tua calon mempelai tidak merestui perkawinan itu'],
  B=['orang tua calon mempelai sudah memberi izin dan ikut mengatur persiapan', 'kedua orang tua calon mempelai merestui perkawinan itu dan ikut mempersiapkannya'],
  beda_pada='peristiwa', beda_maksud='versi A: orang tua tidak memberi izin; versi B: orang tua sudah merestui - berselisih pada PERISTIWA/sikap orang tua')

S(id='g-wali', pokok='pp-pc-alasan-g', urut_abs=123, tingkat='pilihan', keadaan=AL('G'),
  teks='Siapa wali nikah calon istri dan apakah wali itu bersedia menikahkan serta mengetahui rencana perkawinan tersebut ?',
  varian=['Bagaimana sikap wali nikah calon istri terhadap rencana perkawinan itu dan siapa wali yang berhak menikahkannya ?'],
  hal='sikap wali nikah calon istri atas rencana perkawinan', m='sikap wali nikah calon istri atas rencana perkawinan', fam='tahu',
  K=(['wali nasab calon istri yang berhak menikahkannya mengetahui rencana itu dan menolak menikahkannya',
      'ayah atau wali nasab calon istri menolak menjadi wali nikah dalam perkawinan yang direncanakan itu'],
     ['calon istri sudah mempunyai wali nasab yang berhak menikahkannya dan wali itu berkeberatan',
      'wali nikah yang sah bagi calon istri berkeberatan menikahkannya dalam perkawinan yang direncanakan itu']),
  P=(['wali nasab calon istri yang berhak menikahkannya mengetahui rencana itu', 'ayah atau wali nasab calon istri menolak menjadi wali nikah'],
     ['calon istri sudah mempunyai wali nasab yang berhak menikahkannya', 'wali nikah yang sah bagi calon istri berkeberatan menikahkannya']),
  A=['wali nasab calon istri menolak menikahkannya', 'ayah calon istri menolak menjadi wali nikah dalam perkawinan itu'],
  B=['wali nasab calon istri sudah menyetujui dan bersedia menikahkannya', 'ayah calon istri bersedia menjadi wali nikah dalam perkawinan itu'],
  beda_pada='peristiwa', beda_maksud='versi A: wali nasab menolak menikahkan; versi B: wali nasab bersedia - berselisih pada PERISTIWA/sikap wali')

# ------------------------------------------------------------------ alasan H: pengampuan (urutan 131-132)
S(id='h-pengampuan', pokok='pp-pc-alasan-h', urut_abs=131, tingkat='inti', keadaan=AL('H'),
  teks='Siapa calon mempelai yang berada di bawah pengampuan itu dan siapa yang mengurus keperluannya sehari-hari ?',
  varian=['Calon mempelai yang mana yang diampu dan siapa pengampunya serta dari mana saksi mengetahuinya ?'],
  hal='keadaan salah seorang calon mempelai yang berada di bawah pengampuan', m='keadaan salah seorang calon mempelai yang berada di bawah pengampuan', fam='tahu',
  K=(['salah seorang calon mempelai berada di bawah pengampuan dan keluarganya yang mengurus segala keperluan hidupnya',
      'salah seorang calon mempelai berada dalam pengampuan sehingga urusan hidupnya ditangani oleh pengampu dari keluarganya'],
     ['segala keperluan salah seorang calon mempelai diurus oleh pengampunya karena ia berada di bawah pengampuan',
      'salah seorang calon mempelai dalam keadaan diampu dan pengampunya yang bertanggung jawab atas dirinya']),
  P=(['salah seorang calon mempelai berada di bawah pengampuan', 'urusan hidup salah seorang calon mempelai ditangani oleh pengampu dari keluarganya'],
     ['keperluan salah seorang calon mempelai diurus oleh pengampunya', 'salah seorang calon mempelai dalam keadaan diampu']),
  A=['salah seorang calon mempelai berada di bawah pengampuan', 'salah seorang calon mempelai diurus oleh pengampunya dalam segala hal'],
  B=['salah seorang calon mempelai sehat dan mengurus dirinya sendiri', 'calon mempelai itu hidup mandiri dan mengurus keperluannya sendiri'],
  beda_pada='peristiwa', beda_maksud='versi A: calon mempelai berada di bawah pengampuan; versi B: calon mempelai mandiri mengurus dirinya - berselisih pada PERISTIWA/keadaan calon mempelai')

S(id='h-kesengsaraan', pokok='pp-pc-alasan-h', urut_abs=132, tingkat='pilihan', keadaan=AL('H'),
  teks='Kesengsaraan apa yang nyata-nyata akan dialami calon mempelai yang lain bila perkawinan dengan orang yang diampu itu dilangsungkan ?',
  varian=['Penderitaan apa yang akan dialami calon mempelai yang lain bila ia menikah dengan orang yang berada di bawah pengampuan itu ?'],
  hal='kesengsaraan calon mempelai yang lain bila perkawinan dilangsungkan', m='kesengsaraan calon mempelai yang lain bila perkawinan dilangsungkan', fam='tahu',
  K=(['bila perkawinan itu dilangsungkan maka calon mempelai yang lain akan menanggung beban merawat dan menafkahi pasangannya seorang diri',
      'menikah dengan orang yang diampu akan membuat calon mempelai yang lain menderita lahir dan batin'],
     ['perkawinan dengan orang yang berada di bawah pengampuan itu akan mendatangkan penderitaan bagi calon mempelai yang lain',
      'calon mempelai yang lain akan memikul beban hidup yang berat bila perkawinan dengan orang yang diampu itu terlaksana']),
  P=(['calon mempelai yang lain akan menanggung beban merawat pasangannya seorang diri', 'menikah dengan orang yang diampu akan membuat calon mempelai yang lain menderita'],
     ['perkawinan itu akan mendatangkan penderitaan bagi calon mempelai yang lain', 'calon mempelai yang lain akan memikul beban hidup yang berat']))

# ------------------------------------------------------------------ kemudaratan (urutan 151-152)
S(id='m-kemudaratan', pokok='pp-pc-kemudaratan', urut_abs=151, tingkat='inti',
  teks='Kerugian atau kemudaratan apa yang akan timbul bila perkawinan itu tetap dilangsungkan ?',
  varian=['Apa akibat buruk yang akan dialami keluarga dan para calon mempelai bila akad nikah itu jadi dilangsungkan ?'],
  hal='kemudaratan bila perkawinan itu dilangsungkan', m='kemudaratan bila perkawinan itu dilangsungkan', fam='tahu',
  K=(['bila perkawinan itu dilangsungkan maka akan timbul kerugian besar bagi keluarga dan salah seorang calon mempelai',
      'perkawinan yang melanggar syarat itu akan mendatangkan kemudaratan bagi keluarga kedua belah pihak'],
     ['kemudaratan akan menimpa keluarga dan para calon mempelai sendiri bila perkawinan tersebut tetap terlaksana',
      'keluarga dan calon mempelai akan dirugikan lahir dan batin apabila akad nikah itu jadi dilangsungkan']),
  P=(['bila perkawinan itu dilangsungkan maka akan timbul kerugian bagi keluarga', 'perkawinan itu akan mendatangkan kemudaratan bagi keluarga kedua belah pihak'],
     ['kemudaratan akan menimpa keluarga bila perkawinan tersebut terlaksana', 'keluarga akan dirugikan apabila akad nikah itu jadi dilangsungkan']))

S(id='m-istri-anak', pokok='pp-pc-kemudaratan', urut_abs=152, tingkat='pilihan', keadaan=AL('A', terikatPada='calon-suami'),
  teks='Bagaimana nasib istri sah dan anak-anak calon suami terutama nafkah dan perhatian untuk mereka bila perkawinan itu dilangsungkan ?',
  varian=['Apa yang akan terjadi pada nafkah dan perhatian untuk istri sah serta anak-anak calon suami bila ia menikah lagi ?'],
  hal='nafkah dan perhatian untuk istri sah dan anak-anak calon suami bila ia menikah lagi', m='nafkah dan perhatian untuk istri sah dan anak-anak calon suami bila ia menikah lagi', fam='tahu',
  K=(['nafkah dan perhatian calon suami kepada istri sah dan anak-anaknya akan terbagi dan berkurang bila ia menikah lagi',
      'bila calon suami menikah lagi maka istri sah dan anak-anaknya akan kehilangan sebagian nafkah dan perhatian'],
     ['kebutuhan istri sah dan anak-anak calon suami akan terganggu karena nafkah dan waktunya terbagi dengan istri baru',
      'istri sah dan anak-anak calon suami terancam mengalami kekurangan nafkah dan perhatian setelah ia beristri lagi']),
  P=(['nafkah calon suami kepada istri sah dan anak-anaknya akan terbagi bila ia menikah lagi', 'istri sah dan anak-anaknya akan kehilangan sebagian perhatian calon suami'],
     ['kebutuhan istri sah dan anak-anak calon suami akan terganggu', 'istri sah dan anak-anak calon suami terancam kekurangan nafkah']))
